CREATE TABLE IF NOT EXISTS checkins (athlete_id INT NOT NULL, bib VARCHAR(16) NOT NULL, version INT NOT NULL DEFAULT 1, actor BIGINT UNSIGNED NOT NULL, updated DATETIME NOT NULL, PRIMARY KEY(athlete_id), UNIQUE KEY bib_unique(bib), FOREIGN KEY(athlete_id) REFERENCES athletes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS race_enrollments (id INT NOT NULL AUTO_INCREMENT, event_id INT NOT NULL, athlete_id INT NOT NULL, PRIMARY KEY(id), UNIQUE KEY enrolled(event_id,athlete_id), FOREIGN KEY(event_id) REFERENCES events(id), FOREIGN KEY(athlete_id) REFERENCES athletes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS race_relays (id INT NOT NULL AUTO_INCREMENT, event_id INT NOT NULL, name VARCHAR(80) NOT NULL, PRIMARY KEY(id), UNIQUE KEY relay_name(event_id,name), FOREIGN KEY(event_id) REFERENCES events(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS race_members (relay_id INT NOT NULL, event_id INT NOT NULL, athlete_id INT NOT NULL, PRIMARY KEY(relay_id,athlete_id), UNIQUE KEY one_relay(event_id,athlete_id), FOREIGN KEY(relay_id) REFERENCES race_relays(id) ON DELETE CASCADE, FOREIGN KEY(event_id) REFERENCES events(id), FOREIGN KEY(athlete_id) REFERENCES athletes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS race_rounds (id INT NOT NULL AUTO_INCREMENT, event_id INT NOT NULL, stage VARCHAR(8) NOT NULL, heat_no INT NOT NULL, status VARCHAR(12) NOT NULL DEFAULT 'open', version INT NOT NULL DEFAULT 1, actor BIGINT UNSIGNED NOT NULL, updated DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY one_round(event_id,stage,heat_no), FOREIGN KEY(event_id) REFERENCES events(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS race_entries (id INT NOT NULL AUTO_INCREMENT, round_id INT NOT NULL, participant VARCHAR(24) NOT NULL, athlete_id INT NULL, relay_id INT NULL, confirmed TINYINT NOT NULL DEFAULT 0, place INT NULL, PRIMARY KEY(id), UNIQUE KEY one_entry(round_id,participant), UNIQUE KEY one_place(round_id,place), FOREIGN KEY(round_id) REFERENCES race_rounds(id) ON DELETE CASCADE, FOREIGN KEY(athlete_id) REFERENCES athletes(id), FOREIGN KEY(relay_id) REFERENCES race_relays(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS race_audit (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, actor BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, record_id INT NOT NULL, payload LONGTEXT NOT NULL, created DATETIME NOT NULL, PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
